-- Optional local demo data only. All identities are fictional. Does not change registration settings.
USE cendekia_cms;
START TRANSACTION;
INSERT IGNORE INTO spmb_wave_periods(AcademicYear,WaveNumber,Revision,StartDate,EndDate)
SELECT s.AcademicYear,w.Number,COALESCE((SELECT MAX(p.Revision) FROM spmb_wave_periods p WHERE p.AcademicYear=s.AcademicYear AND p.WaveNumber=w.Number),0)+1,
DATE_SUB(UTC_DATE(),INTERVAL (149-30*w.Number) DAY),DATE_SUB(UTC_DATE(),INTERVAL (120-30*w.Number) DAY)
FROM spmb_settings s CROSS JOIN spmb_waves w WHERE s.Id=1;
INSERT INTO spmb_applications (SubmissionKey, RegistrationNumber, AcademicYear, WaveNumber, WaveRevision, StudentName, Nisn, BirthPlace, BirthDate, Gender, PreviousSchool, TargetGrade, GuardianName, GuardianPhone, GuardianEmail, Address, Status, SubmittedAt, UpdatedAt, Version)
SELECT 'd00d0000-0000-4000-8000-000000000001', 'DUMMY-SPMB-001', s.AcademicYear, 1, (SELECT Revision FROM spmb_wave_periods WHERE AcademicYear=s.AcademicYear AND WaveNumber=1 AND StartDate=DATE_SUB(UTC_DATE(), INTERVAL 119 DAY) AND EndDate=DATE_SUB(UTC_DATE(), INTERVAL 90 DAY)), '[Dummy] Ahmad Farhan', '9900000001', 'Purwakarta', '2014-01-15', 'Laki-laki', 'SD Contoh 1 (Dummy)', 'VII', 'Wali Contoh 001 (Dummy)', '08000000001', 'wali001@example.invalid', 'Alamat simulasi 001, Purwakarta (data dummy)', 'Diterima', DATE_SUB(UTC_TIMESTAMP(), INTERVAL 93 DAY), DATE_SUB(UTC_TIMESTAMP(), INTERVAL 93 DAY), 1
FROM spmb_settings s WHERE s.Id = 1 AND NOT EXISTS (SELECT 1 FROM spmb_applications WHERE SubmissionKey = 'd00d0000-0000-4000-8000-000000000001');
